def commons_page(k):
    return 'https://commons.wikimedia.org/wiki/File:'+quote(P[k][0].replace(' ','_'),safe='().,_-')

def photo(k,alt,cls='',loading='lazy'):
    file=P[k][0]
    src='https://commons.wikimedia.org/wiki/Special:FilePath/'+quote(file.replace(' ','_'), safe='().,_-')+'?width=1000'
    return f'<img class="{escape(cls)}" src="{escape(src,quote=True)}" alt="{escape(alt,quote=True)}" loading="{loading}" decoding="async" referrerpolicy="no-referrer" onerror="this.closest(\'figure\')?.classList.add(\'image-error\')">'

def figure(k,alt,label='',cls=''):
    return f'<figure class="photo-card {cls}">{photo(k,alt)}'+(f'<figcaption>{escape(label)}</figcaption>' if label else '')+'</figure>'

def two_photos(a,b,alt_a,alt_b):
    return f'<div class="photo-duo">{figure(a,alt_a)}{figure(b,alt_b)}</div>'

def chips(items): return '<div class="chips">'+''.join('<span class="chip">'+escape(i)+'</span>' for i in items)+'</div>'

def license_link(license_name):
    licenses = {'CC BY 4.0':'https://creativecommons.org/licenses/by/4.0/', 'CC BY 3.0':'https://creativecommons.org/licenses/by/3.0/', 'CC BY 2.0':'https://creativecommons.org/licenses/by/2.0/', 'CC BY-SA 4.0':'https://creativecommons.org/licenses/by-sa/4.0/', 'CC0 1.0':'https://creativecommons.org/publicdomain/zero/1.0/'}
    url = licenses.get(license_name, 'https://commons.wikimedia.org/')
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{escape(license_name)}</a>' 

def footer(keys):
    unique=list(dict.fromkeys(keys))
    credits=''.join(f'<li><a href="{escape(commons_page(k),quote=True)}" target="_blank" rel="noopener noreferrer">{escape(P[k][0])}</a> — {escape(P[k][1])}, {license_link(P[k][2])}</li>' for k in unique)
    return f'''<footer class="site-footer"><div class="shell footer-grid"><div class="footer-intro"><img src="assets/all-things-crochet-logo.webp" alt="All Things Crochet" class="footer-logo"><p>A little yarn, a little joy, and a whole lot of handmade magic.</p></div><div class="footer-links"><strong>Explore</strong><a href="index.html">Home</a><a href="amigurumi.html">Amigurumi</a><a href="tips.html">Tips</a><a href="patterns-tools.html">Patterns &amp; Tools</a></div><div class="footer-links"><strong>Made for makers</strong><a href="amigurumi.html#citrus-pattern">Free amigurumi pattern</a><a href="patterns-tools.html#yardage-calculator">Yardage calculator</a><a href="patterns-tools.html#pet-pattern">Pet toy pattern</a><a href="patterns-tools.html#scarf-pattern">Scarf pattern</a></div></div><div class="shell footer-bottom"><span>© 2026 All Things Crochet · Original tutorials &amp; patterns</span><details class="credits"><summary>Photo credits &amp; licenses</summary><p>Photographs are linked from Wikimedia Commons and credited to their creators; some are presented as inspiration rather than exact samples of the original patterns. Click a photo filename to view its license and source. Internet connection required for photos.</p><ul>{credits}</ul></details></div></footer>'''

def header(active):
    nav=[('HOME','index.html','home'),('AMIGURUMI','amigurumi.html','amigurumi'),('TIPS','tips.html','tips'),('PATTERNS & TOOLS','patterns-tools.html','patterns')]
    links=''.join(f'<a href="{href}" class="nav-link {"is-active" if active==key else ""}" {"aria-current=\"page\"" if active==key else ""}>{name}</a>' for name,href,key in nav)
    return f'''<a class="skip-link" href="#main-content">Skip to content</a><header class="site-header"><div class="shell nav-shell"><a class="brand" href="index.html" aria-label="All Things Crochet, home"><img src="assets/all-things-crochet-logo.webp" alt="All Things Crochet logo"></a><button class="menu-toggle" type="button" aria-label="Open navigation" aria-expanded="false" aria-controls="primary-nav"><span></span><span></span><span></span></button><nav id="primary-nav" class="primary-nav" aria-label="Main navigation">{links}</nav></div></header>'''

def page(name,title,description,content,keys):
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#6a45b8"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)} | All Things Crochet</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="preconnect" href="https://commons.wikimedia.org" crossorigin><link rel="preconnect" href="https://upload.wikimedia.org" crossorigin><link rel="stylesheet" href="styles.css"><script src="script.js" defer></script></head><body class="page-{name}">{header(name)}<main id="main-content">{content}</main>{footer(keys)}</body></html>'''
    (ROOT/({'home':'index.html','amigurumi':'amigurumi.html','tips':'tips.html','patterns':'patterns-tools.html'}[name])).write_text(html,encoding='utf-8')

